/* MacTerm RDP worker. FreeRDP runs in a separate process; stdin/stdout carry
 * bounded framed messages, never command-line passwords or terminal data. */
#include <freerdp/freerdp.h>
#include <freerdp/settings.h>
#include <freerdp/gdi/gdi.h>
#include <freerdp/input.h>
#include <freerdp/error.h>
#include <freerdp/version.h>
#include <freerdp/client/cmdline.h>
#include <freerdp/client/channels.h>
#include <freerdp/channels/channels.h>
#include <freerdp/addin.h>
#include "RDPClipboardCore.h"
#include <winpr/string.h>
#include <winpr/synch.h>
#include <winpr/ssl.h>
#include <winpr/wlog.h>
#include <cjson/cJSON.h>
#include <openssl/opensslv.h>
#include <pthread.h>
#include <stdatomic.h>
#include <arpa/inet.h>
#include <poll.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define IPC_MAX 65536U
#define TILE_MAX (4U*1024U*1024U)
#define PIXEL_MAX 16000000U
#define COMMAND_MAX 128U

typedef struct Command { int kind;UINT16 a,b,c;UINT32 id;char* text;struct Command* next; } Command;
typedef struct State {
 freerdp* instance;HANDLE inputEvent;pthread_mutex_t lock,outputLock;pthread_cond_t condition;
 atomic_bool stopped,connected,inputFailure;int readOnly,requireNLA,clipEnabled;MTClipboard clipboard;unsigned certificateID;int certificatePending,certificateReply;
 Command* first;Command* last;size_t commandCount,commandBytes;
 const char* host;UINT16 port;
} State;
typedef struct {rdpContext context;State* state;} MTContext;
static State* owner(rdpContext* context){return ((MTContext*)context)->state;}
static int valid_size(UINT32 w,UINT32 h){return w>=64&&h>=64&&w<=8192&&h<=8192&&(uint64_t)w*h<=PIXEL_MAX;}
static int write_all(const void* ptr,size_t length){const BYTE* bytes=ptr;while(length){ssize_t n=write(STDOUT_FILENO,bytes,length);if(n<0&&errno==EINTR)continue;if(n<=0)return 0;bytes+=n;length-=(size_t)n;}return 1;}
static int output_packet(State* state,BYTE type,const void* data,size_t length){if(length>TILE_MAX+24)return 0;UINT32 header=htonl((UINT32)length+1);pthread_mutex_lock(&state->outputLock);int ok=write_all(&header,4)&&write_all(&type,1)&&write_all(data,length);pthread_mutex_unlock(&state->outputLock);return ok;}
static int output_json(State* state,cJSON* json){char* text=cJSON_PrintUnformatted(json);cJSON_Delete(json);if(!text)return 0;size_t length=strlen(text);int ok=length<=4194304&&output_packet(state,1,text,length);free(text);return ok;}
static void clip_emit(void* opaque,cJSON* object){output_json((State*)opaque,object);}
static void clip_connected(void* context,const ChannelConnectedEventArgs* event){if(event->name&&!strcmp(event->name,CLIPRDR_SVC_CHANNEL_NAME))mt_clip_attach(&owner((rdpContext*)context)->clipboard,(CliprdrClientContext*)event->pInterface);}
static void clip_disconnected(void* context,const ChannelDisconnectedEventArgs* event){if(event->name&&!strcmp(event->name,CLIPRDR_SVC_CHANNEL_NAME))mt_clip_detach(&owner((rdpContext*)context)->clipboard);}
static BOOL pre_connect(freerdp* instance){State* state=owner(instance->context);if(!state->clipEnabled)return TRUE;if(PubSub_SubscribeChannelConnected(instance->context->pubSub,clip_connected)<0||PubSub_SubscribeChannelDisconnected(instance->context->pubSub,clip_disconnected)<0)return FALSE;return TRUE;}
static BOOL load_channels(freerdp* instance){State* state=owner(instance->context);if(!state->clipEnabled)return TRUE;ADDIN_ARGV* arg=freerdp_static_channel_collection_find(instance->context->settings,CLIPRDR_SVC_CHANNEL_NAME);if(!arg){const char* args[]={CLIPRDR_SVC_CHANNEL_NAME};if(!freerdp_client_add_static_channel(instance->context->settings,1,args))return FALSE;arg=freerdp_static_channel_collection_find(instance->context->settings,CLIPRDR_SVC_CHANNEL_NAME);}PVIRTUALCHANNELENTRY entry=freerdp_load_channel_addin_entry(CLIPRDR_SVC_CHANNEL_NAME,NULL,NULL,FREERDP_ADDIN_CHANNEL_STATIC|FREERDP_ADDIN_CHANNEL_ENTRYEX);return arg&&entry&&freerdp_channels_client_load_ex(instance->context->channels,instance->context->settings,(PVIRTUALCHANNELENTRYEX)entry,arg)==0;}
static int status(State* state,const char* type,const char* message){cJSON* obj=cJSON_CreateObject();cJSON_AddStringToObject(obj,"type",type);cJSON_AddStringToObject(obj,"message",message);return output_json(state,obj);}
static void stop_state(State* state){atomic_store(&state->stopped,1);SetEvent(state->inputEvent);pthread_mutex_lock(&state->lock);pthread_cond_broadcast(&state->condition);pthread_mutex_unlock(&state->lock);if(state->instance&&state->instance->context)freerdp_abort_connect_context(state->instance->context);}
static int read_all(State* state,void* ptr,size_t length){BYTE* bytes=ptr;while(length&&!atomic_load(&state->stopped)){struct pollfd item={.fd=STDIN_FILENO,.events=POLLIN};int ready=poll(&item,1,100);if(ready<0&&errno==EINTR)continue;if(ready<0)return 0;if(!ready)continue;ssize_t n=read(STDIN_FILENO,bytes,length);if(n<0&&errno==EINTR)continue;if(n<=0)return 0;bytes+=n;length-=(size_t)n;}return length==0;}
static cJSON* read_json(State* state){UINT32 wire;if(!read_all(state,&wire,4))return NULL;size_t length=ntohl(wire);if(!length||length>((state->clipEnabled&&atomic_load(&state->connected))?4194304U:IPC_MAX))return NULL;char* text=calloc(length+1,1);if(!text)return NULL;if(!read_all(state,text,length)){free(text);return NULL;}cJSON* json=cJSON_ParseWithLengthOpts(text,length+1,NULL,1);memset(text,0,length);free(text);if(!cJSON_IsObject(json)){cJSON_Delete(json);return NULL;}return json;}
static const char* string_item(cJSON* obj,const char* key,size_t maximum){cJSON* item=cJSON_GetObjectItemCaseSensitive(obj,key);if(!cJSON_IsString(item)||!item->valuestring||strlen(item->valuestring)>maximum)return NULL;return item->valuestring;}
static int number_item(cJSON* obj,const char* key,int minimum,int maximum,int* result){cJSON* item=cJSON_GetObjectItemCaseSensitive(obj,key);if(!cJSON_IsNumber(item)||!isfinite(item->valuedouble)||floor(item->valuedouble)!=item->valuedouble||item->valuedouble<minimum||item->valuedouble>maximum)return 0;*result=(int)item->valuedouble;return 1;}
static int boolean_item(cJSON* obj,const char* key,int* result){cJSON* item=cJSON_GetObjectItemCaseSensitive(obj,key);if(!cJSON_IsBool(item))return 0;*result=cJSON_IsTrue(item);return 1;}
static int send_rectangle(rdpContext* context,int x,int y,int w,int h){State* state=owner(context);rdpGdi* gdi=context->gdi;if(!gdi||!gdi->primary_buffer||!valid_size(gdi->width,gdi->height)||x<0||y<0||w<1||h<1||x>gdi->width-w||y>gdi->height-h)return 0;size_t row=(size_t)w*4;int chunk=(int)(TILE_MAX/row);for(int start=0;start<h;start+=chunk){if(atomic_load(&state->stopped))return 0;int rows=h-start;if(rows>chunk)rows=chunk;size_t bytes=row*(size_t)rows;BYTE* packet=malloc(24+bytes);if(!packet)return 0;UINT32 fields[6]={(UINT32)gdi->width,(UINT32)gdi->height,(UINT32)x,(UINT32)(y+start),(UINT32)w,(UINT32)rows};for(size_t i=0;i<6;i++){UINT32 value=htonl(fields[i]);memcpy(packet+4*i,&value,4);}for(int j=0;j<rows;j++)memcpy(packet+24+row*(size_t)j,gdi->primary_buffer+gdi->stride*(size_t)(y+start+j)+4*(size_t)x,row);int ok=output_packet(state,2,packet,24+bytes);free(packet);if(!ok)return 0;}return 1;}
static BOOL begin_paint(rdpContext* context){if(!context->gdi||!context->gdi->primary||!context->gdi->primary->hdc->hwnd->invalid)return FALSE;context->gdi->primary->hdc->hwnd->invalid->null=TRUE;return TRUE;}
static BOOL end_paint(rdpContext* context){rdpGdi* gdi=context->gdi;if(!gdi||!gdi->primary)return FALSE;HGDI_RGN area=gdi->primary->hdc->hwnd->invalid;if(!area||area->null)return TRUE;int x=area->x<0?0:area->x,y=area->y<0?0:area->y;int64_t right64=(int64_t)area->x+area->w,bottom64=(int64_t)area->y+area->h;int right=(int)(right64<0?0:right64>gdi->width?gdi->width:right64),bottom=(int)(bottom64<0?0:bottom64>gdi->height?gdi->height:bottom64);if(right<=x||bottom<=y)return TRUE;return send_rectangle(context,x,y,right-x,bottom-y);}
static BOOL desktop_resize(rdpContext* context){UINT32 w=freerdp_settings_get_uint32(context->settings,FreeRDP_DesktopWidth),h=freerdp_settings_get_uint32(context->settings,FreeRDP_DesktopHeight);if(!valid_size(w,h))return FALSE;if(!gdi_resize(context->gdi,w,h))return FALSE;memset(context->gdi->primary_buffer,0,(size_t)context->gdi->stride*h);return send_rectangle(context,0,0,(int)w,(int)h);}
static BOOL post_connect(freerdp* instance){rdpContext* context=instance->context;State* state=owner(context);UINT32 w=freerdp_settings_get_uint32(context->settings,FreeRDP_DesktopWidth),h=freerdp_settings_get_uint32(context->settings,FreeRDP_DesktopHeight);UINT32 security=freerdp_settings_get_uint32(context->settings,FreeRDP_SelectedProtocol);if((security!=1&&security!=2&&security!=8)||(state->requireNLA&&security==1)||!valid_size(w,h)||!gdi_init(instance,PIXEL_FORMAT_BGRX32))return FALSE;memset(context->gdi->primary_buffer,0,(size_t)context->gdi->stride*h);context->update->BeginPaint=begin_paint;context->update->EndPaint=end_paint;context->update->DesktopResize=desktop_resize;atomic_store(&state->connected,1);cJSON* obj=cJSON_CreateObject();cJSON_AddStringToObject(obj,"type","connected");cJSON_AddStringToObject(obj,"security",security==1?"TLS":"NLA");return output_json(state,obj);}
static void post_disconnect(freerdp* instance){if(instance->context->gdi)gdi_free(instance);atomic_store(&owner(instance->context)->connected,0);}
static BOOL reject_retry(freerdp* instance,char** user,char** password,char** domain,rdp_auth_reason reason){(void)instance;(void)user;(void)password;(void)domain;(void)reason;return FALSE;}
static BOOL reject_redirect(freerdp* instance){(void)instance;return FALSE;}
static int verify_certificate(freerdp* instance,const BYTE* data,size_t length,const char* host,UINT16 port,DWORD flags){State* state=owner(instance->context);if(!data||!length||length>262144||!host||strcasecmp(host,state->host)||port!=state->port||(flags&(VERIFY_CERT_FLAG_REDIRECT|VERIFY_CERT_FLAG_GATEWAY)))return 0;char* pem=calloc(length+1,1);if(!pem)return 0;memcpy(pem,data,length);pthread_mutex_lock(&state->lock);unsigned ticket=++state->certificateID;state->certificatePending=1;state->certificateReply=0;pthread_mutex_unlock(&state->lock);cJSON* obj=cJSON_CreateObject();cJSON_AddStringToObject(obj,"type","certificate");cJSON_AddNumberToObject(obj,"id",ticket);cJSON_AddStringToObject(obj,"host",host);cJSON_AddNumberToObject(obj,"port",port);cJSON_AddStringToObject(obj,"pem",pem);free(pem);if(!output_json(state,obj))return 0;pthread_mutex_lock(&state->lock);while(state->certificatePending&&!atomic_load(&state->stopped))pthread_cond_wait(&state->condition,&state->lock);int accepted=state->certificateReply&&!atomic_load(&state->stopped);pthread_mutex_unlock(&state->lock);return accepted?2:0;}
static void free_command(Command* command){if(command){if(command->text){memset(command->text,0,strlen(command->text));free(command->text);}free(command);}}
static void* input_thread(void* argument){State* state=argument;for(;;){cJSON* obj=read_json(state);if(!obj)break;const char* type=string_item(obj,"type",32);if(type&&!strcmp(type,"stop")){cJSON_Delete(obj);break;}if(type&&!strcmp(type,"certificateReply")){int id=0,accept=0;if(number_item(obj,"id",1,INT32_MAX,&id)&&boolean_item(obj,"accept",&accept)){pthread_mutex_lock(&state->lock);if(state->certificatePending&&(unsigned)id==state->certificateID){state->certificateReply=accept;state->certificatePending=0;pthread_cond_broadcast(&state->condition);}pthread_mutex_unlock(&state->lock);}cJSON_Delete(obj);continue;}int clipboard=type&&(!strcmp(type,"clipboardRead")||!strcmp(type,"clipboardOffer"));if(!atomic_load(&state->connected)||(state->readOnly&&!clipboard)){cJSON_Delete(obj);continue;}Command* command=calloc(1,sizeof(Command));if(!command){cJSON_Delete(obj);break;}int ok=0,a=0,b=0,c=0;if(clipboard&&state->clipEnabled){ok=number_item(obj,"id",1,INT32_MAX,&a);command->id=(UINT32)a;command->kind=!strcmp(type,"clipboardRead")?6:7;if(command->kind==7){const char* data=string_item(obj,"data",4*((MT_CLIP_WIRE_MAX+2)/3));if(data)command->text=strdup(data);ok=ok&&command->text!=NULL;}}else if(type&&!strcmp(type,"key")){int down=0,extended=0;ok=number_item(obj,"code",0,255,&a)&&boolean_item(obj,"down",&down)&&boolean_item(obj,"extended",&extended);command->kind=1;command->a=(UINT16)a;command->b=(down?0:KBD_FLAGS_RELEASE)|(extended?KBD_FLAGS_EXTENDED:0);}else if(type&&!strcmp(type,"mouse")){ok=number_item(obj,"flags",0,65535,&a)&&number_item(obj,"x",0,8191,&b)&&number_item(obj,"y",0,8191,&c);command->kind=2;command->a=(UINT16)a;command->b=(UINT16)b;command->c=(UINT16)c;}else if(type&&!strcmp(type,"text")){const char* text=string_item(obj,"text",16384);if(text){command->text=strdup(text);ok=command->text!=NULL;command->kind=3;}}else if(type&&!strcmp(type,"ctrlaltdel")){command->kind=4;ok=1;}else if(type&&!strcmp(type,"synchronize")){command->kind=5;ok=number_item(obj,"flags",0,15,&a);command->a=(UINT16)a;}cJSON_Delete(obj);if(!ok){free_command(command);atomic_store(&state->inputFailure,1);status(state,"failed","Invalid or oversized RDP input");break;}size_t size=sizeof(*command)+(command->text?strlen(command->text):0);pthread_mutex_lock(&state->lock);if(command->kind==2&&command->a==PTR_FLAGS_MOVE&&state->last&&state->last->kind==2&&state->last->a==PTR_FLAGS_MOVE){state->last->b=command->b;state->last->c=command->c;pthread_mutex_unlock(&state->lock);free_command(command);SetEvent(state->inputEvent);continue;}if(state->commandCount>=COMMAND_MAX||state->commandBytes+size>8388608){pthread_mutex_unlock(&state->lock);free_command(command);atomic_store(&state->inputFailure,1);status(state,"failed","RDP input queue limit exceeded");break;}if(state->last)state->last->next=command;else state->first=command;state->last=command;state->commandCount++;state->commandBytes+=size;pthread_mutex_unlock(&state->lock);SetEvent(state->inputEvent);}stop_state(state);return NULL;}
static BOOL process_input(State* state){mt_clip_tick(&state->clipboard);ResetEvent(state->inputEvent);for(;;){pthread_mutex_lock(&state->lock);Command* command=state->first;if(command){state->first=command->next;if(!state->first)state->last=NULL;state->commandCount--;state->commandBytes-=sizeof(*command)+(command->text?strlen(command->text):0);}pthread_mutex_unlock(&state->lock);if(!command)break;rdpInput* input=state->instance->context->input;BOOL ok=TRUE;if(command->kind==6)mt_clip_read(&state->clipboard,command->id);else if(command->kind==7)mt_clip_offer(&state->clipboard,command->id,command->text);else if(!state->readOnly&&!atomic_load(&state->stopped)){if(command->kind==1)ok=freerdp_input_send_keyboard_event(input,command->b,(UINT8)command->a);else if(command->kind==2)ok=freerdp_input_send_mouse_event(input,command->a,command->b,command->c);else if(command->kind==3){size_t count=0;WCHAR* text=ConvertUtf8ToWCharAlloc(command->text,&count);ok=text&&count<=4096;for(size_t i=0;ok&&i<count;i++)ok=freerdp_input_send_unicode_keyboard_event(input,0,text[i])&&freerdp_input_send_unicode_keyboard_event(input,KBD_FLAGS_RELEASE,text[i]);free(text);}else if(command->kind==5){ok=freerdp_input_send_synchronize_event(input,command->a);}else if(command->kind==4){ok=freerdp_input_send_keyboard_event(input,0,0x1d)&&freerdp_input_send_keyboard_event(input,0,0x38)&&freerdp_input_send_keyboard_event(input,KBD_FLAGS_EXTENDED,0x53)&&freerdp_input_send_keyboard_event(input,KBD_FLAGS_EXTENDED|KBD_FLAGS_RELEASE,0x53)&&freerdp_input_send_keyboard_event(input,KBD_FLAGS_RELEASE,0x38)&&freerdp_input_send_keyboard_event(input,KBD_FLAGS_RELEASE,0x1d);}}free_command(command);if(!ok)return FALSE;}return TRUE;}
static int configure(State* state,cJSON* obj){const char* type=string_item(obj,"type",32),*host=string_item(obj,"host",255),*user=string_item(obj,"user",1024),*domain=string_item(obj,"domain",1024),*password=string_item(obj,"password",4096),*path=string_item(obj,"configPath",4096);int port=0,width=0,height=0,timeout=0,nla=0,readOnly=0;if(!type||strcmp(type,"connect")||!host||!host[0]||!user||!domain||!password||!path||path[0]!='/'||!number_item(obj,"port",1,65535,&port)||!number_item(obj,"width",64,8192,&width)||!number_item(obj,"height",64,8192,&height)||!valid_size(width,height)||!number_item(obj,"timeout",1,600,&timeout)||!boolean_item(obj,"requireNLA",&nla)||!boolean_item(obj,"viewOnly",&readOnly))return 0;state->host=strdup(host);state->port=(UINT16)port;state->readOnly=readOnly;state->requireNLA=nla;state->clipEnabled=cJSON_IsTrue(cJSON_GetObjectItemCaseSensitive(obj,"clipboard"));state->clipboard.readOnly=readOnly;rdpSettings* settings=state->instance->context->settings;return state->host&&freerdp_settings_set_string(settings,FreeRDP_ServerHostname,host)&&freerdp_settings_set_uint32(settings,FreeRDP_ServerPort,(UINT32)port)&&freerdp_settings_set_string(settings,FreeRDP_Username,user)&&freerdp_settings_set_string(settings,FreeRDP_Domain,domain)&&freerdp_settings_set_string(settings,FreeRDP_Password,password)&&freerdp_settings_set_string(settings,FreeRDP_ConfigPath,path)&&freerdp_settings_set_uint32(settings,FreeRDP_DesktopWidth,(UINT32)width)&&freerdp_settings_set_uint32(settings,FreeRDP_DesktopHeight,(UINT32)height)&&freerdp_settings_set_uint32(settings,FreeRDP_ColorDepth,32)&&freerdp_settings_set_uint32(settings,FreeRDP_TcpConnectTimeout,(UINT32)timeout*1000)&&freerdp_settings_set_bool(settings,FreeRDP_AutoLogonEnabled,TRUE)&&freerdp_settings_set_bool(settings,FreeRDP_NlaSecurity,TRUE)&&freerdp_settings_set_bool(settings,FreeRDP_TlsSecurity,!nla)&&freerdp_settings_set_bool(settings,FreeRDP_RdpSecurity,FALSE)&&freerdp_settings_set_bool(settings,FreeRDP_ExtSecurity,FALSE)&&freerdp_settings_set_bool(settings,FreeRDP_RdstlsSecurity,FALSE)&&freerdp_settings_set_bool(settings,FreeRDP_AadSecurity,FALSE)&&freerdp_settings_set_bool(settings,FreeRDP_RedirectClipboard,state->clipEnabled)&&freerdp_settings_set_bool(settings,FreeRDP_AudioPlayback,FALSE)&&freerdp_settings_set_bool(settings,FreeRDP_AudioCapture,FALSE)&&freerdp_settings_set_bool(settings,FreeRDP_SupportGraphicsPipeline,FALSE)&&freerdp_settings_set_bool(settings,FreeRDP_ExternalCertificateManagement,TRUE)&&freerdp_settings_set_bool(settings,FreeRDP_AutoReconnectionEnabled,FALSE);}
int main(int argc,char** argv){if(argc==2&&!strcmp(argv[1],"--version")){printf("MacTermRDP FreeRDP %s / %s / IPC 1\n",FREERDP_VERSION_FULL,OPENSSL_VERSION_TEXT);return 0;}if(argc!=1)return 2;signal(SIGPIPE,SIG_IGN);State state={0};pthread_mutex_init(&state.lock,NULL);pthread_mutex_init(&state.outputLock,NULL);pthread_cond_init(&state.condition,NULL);mt_clip_init(&state.clipboard,&state,clip_emit,FALSE);freerdp_register_addin_provider(freerdp_channels_load_static_addin_entry,0);atomic_init(&state.stopped,0);atomic_init(&state.connected,0);atomic_init(&state.inputFailure,0);state.inputEvent=CreateEvent(NULL,TRUE,FALSE,NULL);if(!state.inputEvent)return 2;WLog_SetLogLevel(WLog_GetRoot(),WLOG_ERROR);winpr_InitializeSSL(WINPR_SSL_INIT_DEFAULT);state.instance=freerdp_new();if(!state.instance)return 2;state.instance->ContextSize=sizeof(MTContext);state.instance->PreConnect=pre_connect;state.instance->LoadChannels=load_channels;state.instance->PostConnect=post_connect;state.instance->PostDisconnect=post_disconnect;state.instance->AuthenticateEx=reject_retry;state.instance->VerifyX509Certificate=verify_certificate;state.instance->Redirect=reject_redirect;if(!freerdp_context_new(state.instance))return 2;((MTContext*)state.instance->context)->state=&state;cJSON* hello=cJSON_CreateObject();cJSON_AddStringToObject(hello,"type","hello");cJSON_AddNumberToObject(hello,"protocol",1);cJSON_AddNumberToObject(hello,"clipboardProtocol",1);cJSON_AddStringToObject(hello,"core",FREERDP_VERSION_FULL);output_json(&state,hello);cJSON* config=read_json(&state);int valid=config&&configure(&state,config);if(config){cJSON* password=cJSON_GetObjectItemCaseSensitive(config,"password");if(cJSON_IsString(password))memset(password->valuestring,0,strlen(password->valuestring));cJSON_Delete(config);}int exitCode=1;pthread_t reader;int readerStarted=0;if(!valid){status(&state,"failed","Invalid RDP connection configuration");goto cleanup;}if(pthread_create(&reader,NULL,input_thread,&state)){status(&state,"failed","Cannot start RDP input reader");goto cleanup;}readerStarted=1;status(&state,"connecting","Negotiating RDP");int loopFailed=0;if(freerdp_connect(state.instance)){while(!atomic_load(&state.stopped)&&!freerdp_shall_disconnect_context(state.instance->context)){HANDLE events[65];DWORD count=freerdp_get_event_handles(state.instance->context,events,64);if(count==0||count>64){loopFailed=1;break;}events[count++]=state.inputEvent;DWORD result=WaitForMultipleObjects(count,events,FALSE,100);if(result==WAIT_FAILED){loopFailed=1;break;}if(!process_input(&state)||!freerdp_check_event_handles(state.instance->context)){loopFailed=1;break;}}exitCode=loopFailed?1:0;}if(atomic_load(&state.stopped))exitCode=atomic_load(&state.inputFailure)?1:0;UINT32 error=freerdp_get_last_error(state.instance->context);if(!atomic_load(&state.stopped)&&(error!=FREERDP_ERROR_SUCCESS||loopFailed)){cJSON* obj=cJSON_CreateObject();cJSON_AddStringToObject(obj,"type","failed");cJSON_AddNumberToObject(obj,"code",error);cJSON_AddStringToObject(obj,"message",error!=FREERDP_ERROR_SUCCESS?freerdp_get_last_error_name(error):"RDP protocol processing failed");output_json(&state,obj);exitCode=1;}else status(&state,"disconnected","RDP connection closed");
cleanup:stop_state(&state);if(readerStarted)pthread_join(reader,NULL);freerdp_disconnect(state.instance);freerdp_context_free(state.instance);freerdp_free(state.instance);mt_clip_destroy(&state.clipboard);free((void*)state.host);Command* command=state.first;while(command){Command* next=command->next;free_command(command);command=next;}CloseHandle(state.inputEvent);pthread_cond_destroy(&state.condition);pthread_mutex_destroy(&state.lock);pthread_mutex_destroy(&state.outputLock);return exitCode;}
